public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        vector<int> vals;
        for (ListNode* cur = list1; cur; cur = cur->next) vals.push_back(cur->val);
        for (ListNode* cur = list2; cur; cur = cur->next) vals.push_back(cur->val);
        sort(vals.begin(), vals.end());
        ListNode dummy(-1);
        ListNode* tail = &dummy;
        for (int v : vals) {
            tail->next = new ListNode(v);
            tail = tail->next;
        }
        return dummy.next;
    }
};

